+	public T removeItem(T item) {
+		int index = items.indexOf(item);
+		removeAt(index);
+		return item;
+	}
+
+	public T removeAt(int index) {
+		fireIntervalRemoved(this, index, index);
+		return items.remove(index);
+	}
